//! 轻量国际化：中文（默认）/ 英文 / 西班牙文界面文案。
//!
//! 以中文原文为 key，按当前语言查 [`EN`] / [`ES`] 词典，缺失时回退中文原文。这样新增
//! 文案时无需在中文侧做任何改动，只要补对应语言词条即可逐页扩展。
//!
//! 当前覆盖：导航（菜单与分组）、页脚、全站搜索面板、首页与页面标题（浏览器标签）。
//! 页面正文（题库、知识库等）仍在按页增量翻译。

use std::collections::HashMap;
use std::sync::OnceLock;

use ham_web_core::saved_state::keys;
use leptos::prelude::*;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Locale {
  Zh,
  En,
  Es,
}

impl Locale {
  /// 全部可选语言（切换器按此顺序展示）。
  pub const ALL: &'static [Locale] = &[Locale::Zh, Locale::En, Locale::Es];

  #[must_use]
  pub const fn code(self) -> &'static str {
    match self {
      Self::Zh => "zh",
      Self::En => "en",
      Self::Es => "es",
    }
  }

  /// 语言自身名称（各语言下均显示本族名称，不翻译）。
  #[must_use]
  pub const fn label(self) -> &'static str {
    match self {
      Self::Zh => "中文",
      Self::En => "English",
      Self::Es => "Español",
    }
  }

  #[must_use]
  pub fn from_code(s: &str) -> Self {
    if s.eq_ignore_ascii_case("en") {
      Self::En
    } else if s.eq_ignore_ascii_case("es") {
      Self::Es
    } else {
      Self::Zh
    }
  }
}

thread_local! {
  /// 当前界面语言（全局，供 `t` / `set_title` 等非上下文场景读取）。
  static LOCALE: RwSignal<Locale> = RwSignal::new(Locale::Zh);
}

/// 当前界面语言信号。
pub fn locale() -> RwSignal<Locale> {
  LOCALE.with(|l| *l)
}

/// 初始化语言：从 `localStorage` 读取并提供上下文，同时同步 `<html lang>`。
pub fn provide_locale() {
  let signal = locale();
  signal.set(crate::util::storage::get(keys::LOCALE).map_or(Locale::Zh, |s| Locale::from_code(&s)));
  Effect::new(move |_| apply_lang(signal.get()));
}

fn apply_lang(l: Locale) {
  let code = match l {
    Locale::Zh => "zh-CN",
    Locale::En => "en",
    Locale::Es => "es",
  };
  if let Some(root) = crate::util::document().document_element() {
    let _ = root.set_attribute("lang", code);
  }
}

/// 切换语言并持久化。
pub fn set_locale(l: Locale) {
  crate::util::storage::set(keys::LOCALE, l.code());
  locale().set(l);
}

/// 翻译：以中文原文为 key，按当前语言查表，缺失或中文模式返回原文。
pub fn t(key: &str) -> String {
  match locale().get() {
    Locale::Zh => key.to_owned(),
    Locale::En => en_map()
      .get(key)
      .map_or_else(|| key.to_owned(), |v| (*v).to_owned()),
    Locale::Es => es_map()
      .get(key)
      .map_or_else(|| key.to_owned(), |v| (*v).to_owned()),
  }
}

/// 英文词典的哈希索引（惰性构建，把每次翻译从 O(n) 线性扫描降为 O(1)）。
fn en_map() -> &'static HashMap<&'static str, &'static str> {
  static MAP: OnceLock<HashMap<&'static str, &'static str>> = OnceLock::new();
  MAP.get_or_init(|| EN.iter().copied().collect())
}

/// 西班牙文词典的哈希索引。
fn es_map() -> &'static HashMap<&'static str, &'static str> {
  static MAP: OnceLock<HashMap<&'static str, &'static str>> = OnceLock::new();
  MAP.get_or_init(|| ES.iter().copied().collect())
}

/// 带占位符的翻译：把词条中的 `{}` 按顺序替换为 `args`（数量不足时保留剩余占位符）。
pub fn tf(key: &str, args: &[&str]) -> String {
  let mut s = t(key);
  for a in args {
    match s.find("{}") {
      Some(pos) => s.replace_range(pos..pos + 2, a),
      None => break,
    }
  }
  s
}

/// 题库类别标签（按语言调整词序）：中文「B 类」、英文「Class B」、西班牙文「Clase B」。
pub fn bank_class(bank: &str) -> String {
  match locale().get() {
    Locale::Zh => format!("{bank} 类"),
    Locale::En => format!("Class {bank}"),
    Locale::Es => format!("Clase {bank}"),
  }
}

